<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { listarStock, obtenerCompromiso, urlExportarStock, type CatalogoStock, type StockComprometido } from '../services/stock'
const rows=ref<StockComprometido[]>([]),almacenes=ref<CatalogoStock[]>([]),estados=ref<Record<string,string>>({}),summary=reactive({fisico:0,comprometido:0,disponible:0,alertas:0}),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref<StockComprometido|null>(null)
const filters=reactive({almacen:'',estado:'',pedido:'',fecha_desde:'',fecha_hasta:''})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarStock({...filters,page:next});rows.value=r.data;almacenes.value=r.almacenes;estados.value=r.estados;Object.assign(summary,r.resumen);total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{almacen:'',estado:'',pedido:'',fecha_desde:'',fecha_hasta:''});load(1)}
async function show(row:StockComprometido){try{detail.value=await obtenerCompromiso(row.id)}catch(e){error.value=message(e)}}
function exportUrl(format:'xlsx'|'pdf'){return urlExportarStock(format,{...filters})}
const number=(v=0)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo consultar el stock.'
function stateClass(state:number){return ['','reserved','partial','consumed','cancelled'][state]||'cancelled'}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Stock comprometido</nav><header class="hero"><div class="mark">ST</div><div><small>MIA · ALMACÉN</small><h1>Compromisos de stock</h1><p>Supervisa las existencias reservadas para la atención de pedidos.</p></div><div class="exports"><a :href="exportUrl('xlsx')" target="_blank">Exportar Excel</a><a class="pdf" :href="exportUrl('pdf')" target="_blank">Exportar PDF</a></div></header><p v-if="error" class="flash">{{error}}</p>
<section class="metrics"><article><small>STOCK FÍSICO</small><b>{{number(summary.fisico)}}</b></article><article><small>COMPROMETIDO PENDIENTE</small><b>{{number(summary.comprometido)}}</b></article><article><small>DISPONIBLE</small><b :class="{negative:summary.disponible<0}">{{number(summary.disponible)}}</b></article><article class="alert"><small>ALERTAS</small><b>{{summary.alertas}}</b></article></section>
<section class="filters"><label>Almacén<select v-model="filters.almacen"><option value="">Todos</option><option v-for="x in almacenes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="(name,id) in estados" :key="id" :value="id">{{name.replaceAll('_',' ')}}</option></select></label><label>Fecha desde<input v-model="filters.fecha_desde" type="date"></label><label>Fecha hasta<input v-model="filters.fecha_hasta" type="date"></label><label>Pedido<input v-model.trim="filters.pedido" placeholder="Número de pedido" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button><button class="soft" @click="clear">Limpiar</button></section>
<section class="table-card"><header><div><small>RESULTADOS</small><h2>Stock reservado por pedido</h2></div><b>{{total}} compromisos</b></header><div v-if="loading" class="empty">Consultando existencias…</div><div v-else-if="!rows.length" class="empty">No se encontraron compromisos de stock.</div><div v-else class="scroll"><table><thead><tr><th>Ítem</th><th>Unidad</th><th>Pedido</th><th>Almacén</th><th class="right">Físico</th><th class="right">Comprometido</th><th class="right">Disponible</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{warning:row.disponible<0}"><td><b>{{row.item}}</b><small>Código {{row.item_id}}</small></td><td>{{row.unidad}}</td><td>#{{row.pedido||String(row.pedido_id).padStart(6,'0')}}</td><td>{{row.almacen}}</td><td class="right">{{number(row.stock_fisico)}}</td><td class="right">{{number(row.stock_comprometido_pendiente)}}</td><td class="right available" :class="{negative:row.disponible<0}">{{number(row.disponible)}}</td><td><span class="badge" :class="stateClass(row.estado)">{{row.estado_nombre}}</span></td><td>{{row.fecha}}</td><td><button class="detail-btn" @click="show(row)">Detalle</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>DETALLE DEL COMPROMISO</small><h2>{{detail.item}}</h2></div><button @click="detail=null">×</button></header><div class="info"><div><small>PEDIDO</small><b>#{{detail.pedido||detail.pedido_id}}</b></div><div><small>ALMACÉN</small><b>{{detail.almacen}}</b></div><div><small>SOLICITANTE</small><b>{{detail.solicitante||'—'}}</b></div><div><small>ÁREA</small><b>{{detail.area||'—'}}</b></div></div><div class="balance"><div><small>Comprometido inicial</small><b>{{number(detail.cantidad_comprometida)}}</b></div><span>−</span><div><small>Cantidad consumida</small><b>{{number(detail.cantidad_consumida)}}</b></div><span>=</span><div><small>Pendiente</small><b>{{number(detail.stock_comprometido_pendiente)}}</b></div></div><p>Stock físico actual: <b>{{number(detail.stock_fisico)}} {{detail.unidad}}</b> · Disponible luego de compromisos: <b :class="{negative:detail.disponible<0}">{{number(detail.disponible)}}</b></p><footer><button @click="detail=null">Cerrar</button></footer></section></div></div></template>
