border-collapse:collapse;font-size:.52rem}th,td{padding:9px 8px;border-bottom:1px solid #e8ecee;text-align:left;white-space:nowrap}th{color:#66757c;background:#f5f7f8;font-size:.48rem}td:first-child{white-space:normal;min-width:160px}td small{display:block;margin-top:2px;color:#8c989e}.right{text-align:right}.available{color:#27825d;font-weight:700}.warning{background:#fffafa}.badge{padding:4px 6px;border-radius:9px;font-size:.45rem}.reserved{color:#25728f;background:#e6f5fa}.partial{color:#9b6b22;background:#fff5dd}.consumed{color:#277354;background:#e6f7ee}.cancelled{color:#68767d;background:#edf0f2}.detail-btn{border:0;color:var(--accent);background:none;font-size:.5rem}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.table-card footer button,.dialog button{background:var(--accent)}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.info{display:grid;grid-template-columns:1fr 1fr;gap:7px}.info div{padding:9px;border-radius:6px;background:#f5f7f8}.info b,.info small{display:block;font-size:.55rem}.balance{margin:12px 0;padding:12px;display:flex;align-items:center;justify-content:space-between;border-radius:8px;background:#f7edf1}.balance div{text-align:center}.balance small,.balance b{display:block}.balance b{font-size:.8rem}.dialog p{font-size:.57rem}.dialog footer{text-align:right}@media(max-width:900px){.hero{flex-wrap:wrap}.exports{margin-left:0}.metrics{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}
